from kd_common import *
i=3
Z=lambda q,a:[('z',q),('b',a)]
def kundike(): return '<rect x="-60" y="-14" width="120" height="14" fill="#9a8a7a"/><rect x="-46" y="-30" width="92" height="16" fill="#4aa3df"/><path d="M-46 -30 h92" stroke="#bfe3ff" stroke-width="3"/>'
def kani(): return '<ellipse rx="40" ry="8" fill="#c9a227"/><ellipse cy="-6" rx="32" ry="7" fill="#f4f1ea"/><ellipse cy="-24" rx="12" ry="16" fill="#8a5a2a"/><path d="M-12 -24 h24" stroke="#c0392b" stroke-width="4"/><path d="M-6 -40 q6 -10 12 0" stroke="#2f8a3a" stroke-width="3" fill="none"/>'
fw=foreword(i,['On the first day of the solar month of Tulā, in mid-October, a small tank on the Brahmagiri hills becomes the centre of Kodagu. At a moment fixed by astrologers, water wells up in the <b>Brahma Kuṇḍike</b> at <b>Talakāverī</b>, and the river Kāverī is said to be born again. This is <b>Kāverī Saṅkramaṇa</b>.',
 'This part tells the legend of Kāverī and Agastya, describes Talakāverī and Bhāgamaṇḍala, the <b>tīrthōdbhava</b>, the holy water taken home, the <b>Kanni Pūje</b> in every house, the food and the walk of the pilgrims, and the story of the Kodava sari.',
 'The river continues to '+L('/temples-of-india/triranga/','the Triraṅga')+' downstream. Previous: '+L('/kodagu/kailpodh/','Kailpoḷd')+'. Next: '+L('/kodagu/igguthappa/','Igguthappa')+'.'],Z('Is the river really born every year?','The spring flows all year. On this day the water rises visibly at the fixed moment. Faith calls that her birth.'))
gl=glance([('Name','Kāverī Saṅkramaṇa, Tulā Saṅkramaṇa, Kāverī Caṅgrāndi'),('When','First day of Tulā (Kodava Tulyār), mid-October'),('Where','Talakāverī on the Brahmagiri; Bhāgamaṇḍala below'),('Main event','Tīrthōdbhava: water wells up in the Brahma Kuṇḍike'),('Holy water','Carried home and kept all year'),('At home','Kanni Pūje: Kāverī honoured on a tray of rice'),('Food','Vegetarian: dosa and pumpkin curry'),('Fair','Kāverī Jātre at Bhāgamaṇḍala'),('Goddess','Kāverī Amma (Kāveramma), Kodava kuladēvī'),('Distance','About 47 km from Madikeri')],
 S('Pilgrims at the Brahma Kuṇḍike tank on the hills as water rises',hills(560,110,'#5a9a5a')+g(280,200,1.6,kundike())+''.join(g(80+k*90,210,.9,[kodava_man(),kodava_woman()][k%2]) for k in range(6))+g(280,150,.6,flame()),'#d8e8f0',215),Z('Why Tulā?','The sun enters Tulā (Libra). That saṅkramaṇa is hers.'),'The river <b>is born again</b>.')
leg=story('legend','THE LEGEND','Kāverī and Agastya',strip('Three panels: the sage Kavera with his daughter; Agastya with his water pot; the river rushing away and the Kodava women trying to hold her',
 [('<rect width="144" height="190" fill="#fff3cf"/>'+g(50,180,.8,god('#f4f1ea'))+g(100,180,.7,devi(sari='#4aa3df',items=())),'#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(60,180,.8,god('#e0a800'))+'<path d="M90 140 h24 l-4 20 h-16z" fill="#c9a227"/>','#fff3cf'),
  ('<rect width="144" height="190" fill="#d8e8f0"/><path d="M0 150 C40 120 90 170 144 130" stroke="#4aa3df" stroke-width="14" fill="none"/>'+g(40,180,.6,kodava_woman())+g(100,180,.6,kodava_woman('#2a9d6f')),'#d8e8f0')],
 ['the daughter','the water pot','the river runs']),'A Purāṇic legend (Kāverī Purāṇa, Skanda Purāṇa) as told in Kodagu; versions differ.',
 ['The sage <b>Kavera</b> was given a daughter by Brahmā; she was named <b>Kāverī</b>.','She married the sage <b>Agastya</b> on one condition: he must never leave her alone. He kept her in his water pot.','When he left her once, she flowed out of the pot and rushed away as a river. The people tried to stop her; she promised to return each year at Saṅkramaṇa.'])
sari=reading('sari','THE SARI LEGEND','Why the pleats are at the back',S('Kodava women in saris with pleats at the back beside a rushing river',g(280,160,1,'<path d="M-280 20 C-150 -30 -50 50 280 -10" stroke="#4aa3df" stroke-width="26" fill="none"/>')+g(170,215,1.8,kodava_woman())+g(390,215,1.8,kodava_woman('#2a9d6f')),'#d8e8f0',230),
 ['<b>The story.</b> When Kāverī rushed away, the Kodavas, especially the women, tried to hold her back.','<b>The force.</b> The force of the water swept their sari pleats round to the back.','<b>Ever since.</b> Kodava women wear the sari with the pleats at the back, in honour of that day.','<b>A legend.</b> This is a tradition, told with love; dress historians may explain it other ways.','<b>See.</b> The dress is described in '+L('/kodagu/kodavas/','Part 1')+'.'],Z('Is it true?','It is the Kodava answer, and the one every grandmother gives.'),'A sari <b>shaped by a river</b>.')
tala=reading('talakaveri','TALAKĀVERĪ','The source on the Brahmagiri',S('Steps up the hill to a tank and small shrines; the hilltop beyond',hills(560,90,'#5a9a5a')+g(280,210,1.8,kundike())+g(120,200,1,tulu_temple())+g(440,200,1,tulu_temple())+'<path d="M380 180 l40 -60 l40 -40" stroke="#9a8a7a" stroke-width="10" fill="none"/>','#d8e8f0',230),
 ['<b>The place.</b> Talakāverī (“head of the Kāverī”) lies on the Brahmagiri hills, about 47 km from Madikeri.','<b>Brahma Kuṇḍike.</b> The source is a small sacred tank, the <b>Brahma Kuṇḍike</b>; a larger bathing tank is in front.','<b>Shrines.</b> Small shrines nearby honour Agastya’s liṅga (Agastyēśvara) and Gaṇapati.','<b>The hilltop.</b> Steps lead up the hill to a view across the Ghats.','<b>Underground.</b> From the source the water goes underground and reappears lower down.'],Z('Can you see the river at the source?','Just a spring and a tank. The great river begins small.'),'The great river <b>begins as a spring</b>.')
bhaga=reading('bhagamandala','BHĀGAMAṆḌALA','The confluence below',S('Three streams meeting before a Kerala-style temple',g(280,140,1,'<path d="M-260 -40 L0 40 M260 -40 L0 40 M0 -60 L0 40" stroke="#4aa3df" stroke-width="16" fill="none" stroke-dasharray="0"/>')+g(280,215,1.6,tulu_temple()),'#d8e8f0',230),
 ['<b>Triveṇī.</b> At Bhāgamaṇḍala the Kāverī meets the <b>Kannike</b> and a hidden third stream, the <b>Sujyōti</b>.','<b>The temple.</b> The <b>Bhagaṇḍēśvara</b> temple stands here in the Kerala style (see '+L('/kodagu/temples/','Part 10')+').','<b>First stop.</b> Pilgrims bathe at the confluence before climbing to Talakāverī.','<b>Pathaya.</b> Before the day, rice is offered to the temple granary at a fixed time, a ritual announced in the press.','<b>Pinda.</b> In the following month families offer rites for ancestors here. (As reported.)'],Z('Three rivers?','Two you see, one you believe in. Like Prayāga.'),'Where three waters <b>meet</b>.')
tirtha=reading('tirthodbhava','TĪRTHŌDBHAVA','The moment the water rises',S('Crowds at night around the tank as water swells and a priest raises a lamp',g(280,170,2,kundike())+'<path d="M260 120 q20 -30 40 0" stroke="#bfe3ff" stroke-width="5" fill="none"/>'+''.join(g(60+k*70,215,.7,[kodava_man(),kodava_woman()][k%2]) for k in range(7))+g(280,80,.8,flame()),'#20243a',215),
 ['<b>The hour.</b> Astrologers fix the moment of Tulā Saṅkramaṇa; it may fall by day or at night.','<b>The rise.</b> At that moment water is seen to well up in the Brahma Kuṇḍike: the <b>tīrthōdbhava</b>, “the birth of holy water”.','<b>The crowd.</b> Thousands wait; priests offer worship; the water is sprinkled on the crowd.','<b>A saying.</b> Kodavas say: to see a sea of humanity go on Saṅkramaṇa; to see the goddess, go another day.','<b>Bathing.</b> Pilgrims bathe in the tank and at Bhāgamaṇḍala.'],Z('How does it rise?','Pilgrims see it, priests confirm it. We leave the explanation to faith.'),'The water <b>wells up</b>.')
water=reading('water','THE HOLY WATER','Tīrtha taken home',S('A woman carries a small pot of holy water home; it is kept near the lamp',g(160,215,1.8,kodava_woman())+g(200,140,.8,'<path d="M-10 0 h20 l-4 -20 h-12z" fill="#c9a227"/>')+g(420,215,1.6,hanging_lamp())+g(420,200,.8,'<path d="M-10 0 h20 l-4 -20 h-12z" fill="#c9a227"/>'),'#fff3cf',230),
 ['<b>Collected.</b> The tīrtha is collected in pots and bottles and carried home.','<b>Shared.</b> It is distributed to families who could not go.','<b>Kept.</b> It is preserved in every Kodava home until the next Saṅkramaṇa.','<b>For the dying.</b> It is believed that a dying person given this water attains salvation.','<b>In rites.</b> It is used in rituals through the year.'],Z('Water kept for a year?','In the prayer corner, beside the lamp. A sip of the mother for every need.'),'The mother <b>comes home in a pot</b>.')
kanni=reading('kanni','KANNI PŪJE','Kāverī on a tray',S('A brass tray of rice with a decorated coconut, betel, flowers and a lamp before the family',g(280,200,2.2,kani())+g(180,200,1,lamp())+g(380,200,1,lamp())+g(100,215,1.1,kodava_woman())+g(470,215,1.1,kodava_man()),'#fff3cf',220),
 ['<b>Next day.</b> On the day after the tīrthōdbhava, Kāverī is worshipped in every Kodava home in a simple ritual, the <b>Kanni Pūje</b>.','<b>The tray.</b> A brass or silver tray is heaped with rice; on it a decorated coconut (or a cucumber, in some homes) is placed, dressed as the goddess.','<b>Beside it.</b> Fresh flowers, three betel leaves, areca nuts and a lit lamp.','<b>Women lead.</b> Married women of the house commonly perform it; the family prays and thanks Kāveramma for the year’s bounty.','<b>Symbol.</b> Kāverī is honoured not as an idol but through the decorated symbol.'],Z('A coconut as the goddess?','Dressed in silk and flowers, on a bed of rice. The river is a mother, not a statue.'),'The goddess <b>on a bed of rice</b>.')
food=cards('food','THE FOOD','A vegetarian day',fig_row('Dosa, pumpkin curry, a lamp and a coconut',[('<ellipse rx="26" ry="10" fill="#e9c27a"/>',1.2),('<path d="M-20 0 h40 l-6 -22 h-28z" fill="#e08a2a"/>',1.2),(kani(),.8),(lamp(),1)],['dosa','pumpkin curry','kanni','lamp'],gy=150),
 [('🥞','Dosa','Vegetarian dosa is cooked for the day.'),('🎃','Pumpkin curry','A pumpkin curry is the typical partner.'),('🚫','No meat','The Saṅkramaṇa meal is vegetarian in many homes, unusual in Kodagu.'),('🍚','Rice','Rice from the Kanni tray may be cooked later.'),('🎪','Jātre','Fair stalls at Bhāgamaṇḍala.'),('🙏','First the goddess','The meal follows the Kanni Pūje.')],None,'A rare <b>vegetarian feast</b>.',intro='For a pork-loving community, the choice of a vegetarian menu shows how sacred the day is.')
walk=reading('walk','THE PILGRIMS','Barefoot with the dudi',S('Kodavas walking uphill barefoot, one beating a hand-drum',hills(560,110,'#5a9a5a')+''.join(g(80+k*90,210,1,[kodava_man(),kodava_woman()][k%2]) for k in range(5))+g(500,190,1,dudi()),'#d8e8f0',215),
 ['<b>The walk.</b> Many Kodavas walk barefoot from Bhāgamaṇḍala up to Talakāverī on the day.','<b>Dress.</b> Men in white or black kupya and chele, women in Kodava saris.','<b>Drum.</b> They beat the <b>dudi</b>, the hand-drum, and sing the old songs (bāḷō pāṭ).','<b>Everyone.</b> People of all communities, and pilgrims from far away, come too.','<b>Fair.</b> The Kāverī Jātre offers shopping, food and rides.'],Z('Barefoot up a hill?','Seven or eight kilometres. Grandmothers do it.'),'Up the hill <b>to the mother</b>.')
endp=end(i,['<b>When.</b> First day of Tulā, mid-October.','<b>Where.</b> Talakāverī’s Brahma Kuṇḍike; Bhāgamaṇḍala below.','<b>Event.</b> Tīrthōdbhava: water wells up at a fixed moment.','<b>Home.</b> Holy water kept all year; Kanni Pūje on a tray of rice.','<b>Legend.</b> Kāverī, Agastya and the sari pleats at the back.'],'Part 5 is Igguthappa, god of rain and rice.','The mother returns')
src=sources([('Festival:','Deccan Herald, “Celebrating river Kaveri’s birth” and “Celebrating birth river” (Kanni Puje tray, holy water, saying); Karnataka Tourism and Incredible India (date, Brahma Kundike, jātre, 47 km); Nature Infocus (sari legend, pledge to return); Tirthayatra (barefoot walk, dudi, bāḷō pāṭ); Star of Mysore (Bhāgamaṇḍala pathaya rite); Deccan Herald “Revering nature, culture” (vegetarian dosa and pumpkin curry; later rites).'),('Legend:','Kāverī Purāṇa as told in Kodagu.')],'the cucumber variant and the pinda month are as reported; the legend is told in brief and versions differ.','Water rising is presented as believers describe it.')
finish(i,'PART 4 OF 12 · TALAKĀVERĪ · TĪRTHA · KANNI PŪJE',covart('Pilgrims at the source tank on the hills as water rises at night',hills(440,90,'#5a9a5a')+g(220,180,1.4,kundike())+g(220,120,.6,flame())+g(90,190,.9,kodava_woman())+g(350,190,.9,kodava_man())),'The mother returns',
 '<b>Kāverī Saṅkramaṇa</b> at Talakāverī: the legend of Kāverī and Agastya, the <b>tīrthōdbhava</b> at the Brahma Kuṇḍike, the holy water taken home and the <b>Kanni Pūje</b> in every Kodava house.',
 'Kāverī Saṅkramaṇa (Tulā Saṅkramaṇa) explained and illustrated: Kāverī and Agastya legend, Talakāverī and Bhāgamaṇḍala, tīrthōdbhava, holy water, Kanni Pūje, vegetarian food, pilgrims and the Kodava sari legend.',
 [fw,gl,leg,sari,tala,bhaga,tirtha,water,kanni,food,walk,endp,src])
